# owner: platform
import unittest

from hourglass.timesheet import timesheet_rows
from hourglass.models import Shift, Span

def make_shift(worker, start, end):
    return Shift(worker, "mon", Span(start * 60, end * 60))

class TimesheetTests(unittest.TestCase):
    def test_busiest_first(self):
        shifts = [make_shift("Ana", 9, 10), make_shift("Ben", 9, 13), make_shift("Ana", 11, 12)]
        self.assertEqual(
            timesheet_rows(shifts),
            ["Ben: 1 shifts, 4.0 hours", "Ana: 2 shifts, 2.0 hours"]
        )

    def test_one_decimal(self):
        rows = timesheet_rows([Shift("Ana", "tue", Span(540, 590))])
        self.assertEqual(rows, ["Ana: 1 shifts, 0.8 hours"])

    def test_empty(self):
        with self.assertRaises(ValueError):
            timesheet_rows([])

    def test_blank_worker(self):
        with self.assertRaises(ValueError):
            timesheet_rows([make_shift("  ", 9, 10)])
